!function(r){function t(t){for(var i,n,p=t[0],o=t[1],u=t[2],s=0,g=[];s<p.length;s++)n=p[s],Object.prototype.hasOwnProperty.call(e,n)&&e[n]&&g.push(e[n][0]),e[n]=0;for(i in o)Object.prototype.hasOwnProperty.call(o,i)&&(r[i]=o[i]);for(c&&c(t);g.length;)g.shift()();return m.push.apply(m,u||[]),a()}function a(){for(var r,t=0;t<m.length;t++){for(var a,n=m[t],p=!0,o=1;o<n.length;o++)a=n[o],0!==e[a]&&(p=!1);p&&(m.splice(t--,1),r=i(i.s=n[0]))}return r}function i(t){if(n[t])return n[t].exports;var a=n[t]={i:t,l:!1,exports:{}};return r[t].call(a.exports,a,a.exports,i),a.l=!0,a.exports}var n={},e={30:0},m=[];i.m=r,i.c=n,i.d=function(r,t,a){i.o(r,t)||Object.defineProperty(r,t,{enumerable:!0,get:a})},i.r=function(r){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(r,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(r,"__esModule",{value:!0})},i.t=function(r,t){if(1&t&&(r=i(r)),8&t)return r;if(4&t&&"object"==typeof r&&r&&r.__esModule)return r;var a=Object.create(null);if(i.r(a),Object.defineProperty(a,"default",{enumerable:!0,value:r}),2&t&&"string"!=typeof r)for(var n in r)i.d(a,n,function(t){return r[t]}.bind(null,n));return a},i.n=function(r){var t=r&&r.__esModule?function(){return r.default}:function(){return r};return i.d(t,"a",t),t},i.o=function(r,t){return Object.prototype.hasOwnProperty.call(r,t)},i.p="";var p=window.webpackJsonp=window.webpackJsonp||[],o=p.push.bind(p);p.push=t,p=p.slice();for(var u=0;u<p.length;u++)t(p[u]);var c=o;m.push([18,0]),a()}({18:function(r,t,a){"use strict";a.r(t);var i=a(0);Object(i.a)("ru","army",a(19),a(1))},19:function(r){r.exports=JSON.parse('{"category":[{"name":"苏联","link":"ru_shortcut"},{"name":"陆战武器","link":"ru_army"},{"name":"坦克","link":"ru_army#ru_army_tank"}],"model":"T-28/T-35多炮塔坦克","description":"<h6>综述：</h6><p>二战期间，苏联曾研制了二种多炮塔坦克，一种是T-28中型坦克，另一种是T-35重型坦克，两种坦克具有一个共同的特点，就是它们都有一个外形与一般坦克不同的多个炮塔（这些炮塔并不都是用来安装火炮的）；这些多炮塔坦克在1932年就开始研发，约在1933年开始服役，但由于生产数量不多，且本身存在不少技术上的问题，武器与防护能力也较弱，因此它们大多只参加了苏芬战争和初期的苏联卫国战争，很快就停止生产并退出部队。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{text}}T-28中型坦克四视图{{image}}imgs/ru/army/ru_army_tankt2835_11.jpg{{text}}1941年秋季，苏联西部战线，苏军一辆不明单位的T-28中型坦克。{{image}}imgs/ru/army/ru_army_tankt2835_12.jpg{{text}}1942年冬季，苏联列宁格勒地区，苏军第51独立坦克营的一辆T-28中型坦克。{{image}}imgs/ru/army/ru_army_tankt2835_13.jpg{{text}}1944年6月，芬兰卡累利亚峽谷，苏军第91独立坦克团的一辆T-28中型坦克。{{image}}imgs/ru/army/ru_army_tankt2835_14.jpg","description":"<h6>T-28中型坦克</h6><p>T-28有3个炮塔，1933年8月装备苏军，在1933年至1940年生产期间对悬挂系统、火炮和装甲进行了4次改进。T-28有一个中央炮塔，初期装备一门45mmm火炮，后又改装为72.6mm火炮，最后又用26倍口径身管的L-10火炮替代了16.5倍口径身管的火炮；T-28的主炮塔下有两个小炮塔，各装备1挺76.2mm机枪；在后期生产的T-28坦克的主炮塔上，还多装了一挺高射机枪。T-28有较快的车速，但其多轮悬挂的履带装置却容易使坦克陷入泥泞中，此外动力与传动系统也存在不少问题，装甲也显薄弱，因此使其作战效能大打折扣。</p><p>性能参数（仅供参考）：</p><p>车长：7.44m，车宽：2.86m，车高：2.86m，车重约32t；乘员6人；</p><p>最高车速：37KM/h，最大行程：220km；</p><p>装甲厚度：前装甲（前期）50mm，（后期）80mm；</p><p>武器配备：1门76.2mm火炮， 3 挺7.62mm机枪（含1 挺高射机枪）。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>车体上（面向前方）有3个炮塔，大炮塔在上，二个小炮塔（机枪塔）在下。</li><li>悬挂系统两侧各有6对共12个小负重轮。</li><li>履带外侧加有装甲挡板。</li></ol></span>","caption":""},{"image":"{{text}}T-35重型坦克{{image}}imgs/ru/army/ru_army_tankt2835_21.jpg{{text}}1941年6月，苏联地区，隶属苏军第8机械化军第34装甲师第68坦克团的一辆T-35重型坦克。{{image}}imgs/ru/army/ru_army_tankt2835_22.jpg{{text}}1941年11月，隶属莫斯科陆军军官学校机械化与机动化混成团的一辆T-35重型坦克。{{image}}imgs/ru/army/ru_army_tankt2835_23.jpg","description":"<h6>T-35重型坦克</h6><p>T-35重型坦克有5个炮塔，1个主炮塔，2个次级炮塔，2个机枪塔；这也是当时参战各国中唯一有5个炮塔的坦克。该坦克体积大，但装甲薄弱，且因动力不足，造成越障困难，机动性很差，在战场上生存能力极低；该坦克虽然火炮多，但射击准确率却很低，且构造复杂，造价亦高，因此一共只生产了大约60辆。</p><p>性能参数（仅供参考）：</p><p>车长：9.7m，车宽：3.2m，车高：3.4m，车重约50t；乘员11人；</p><p>最高车速：30KM/h，最大行程：150km；</p><p>装甲厚度：前装甲30mm；</p><p>武器配备：1门76.2mm火炮，2门45mm火炮， 6挺7.62mm机枪，1 挺高射机枪。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>有5个炮塔，前方最上层为主炮塔（装76.2mm火炮 )，前方主炮下层为2个小炮塔（各装一门45mm火炮和一挺机枪），主炮塔后方有2个小炮塔（各装一门45mm火炮和一挺机枪）。</li><li>悬挂系统两侧各有4对（共8个）小负重轮，有防护挡板。</li></ol></span>","caption":""}],"part2title":"战场上的T-28与T-35坦克","part2description":"<article><p>T-28中型坦克装备部队后参加了苏芬战争，初期在战场上的表现并不理想，苏军在战争开始时有两个T-28坦克旅（第10和第20重型装甲旅），主要用作支援步兵进攻，但在芬兰军的反坦克炮火攻击下，两个旅的T-28坦克都损失惨重，后期T-28将装甲增加至80mm，其余部分都增加至40mm, 加强了坦克的装甲防护，T-28在1940年突破芬兰军的曼纳海姆防线的进攻中起了重要作用。</p><p>T-35重型坦克则装备了苏军第5 独立重型坦克旅（后备部队），在战场上主要是用于支援该旅的T-28坦克作战用（有资料说T-35重型坦克也参加了苏芬战争）。</p><p>苏联卫国战争开始，T-28和T-35都投入了战斗，战损极大，到战争中期，已极少见到这些坦克的身影（到1944年还有少量T-28坦克）。T-35甚至在莫斯科保卫战中埋在工事中作固定炮台用，其余则编入苏联第8机械化军第34 坦克师的第67、68坦克团，后全部损失在乌克兰附近的的夏季战役中，其中很多是因机械故障而放弃，被德军完整缴获。</p></article>","part2content":[{"image":"imgs/ru/army/ru_army_tankt2835_31.jpg","description":"1939年9月17日，苏军第21重坦克旅的一辆T-28中型坦克正在穿越波兰东部的乌萨河。","caption":""},{"image":"imgs/ru/army/ru_army_tankt2835_32.jpg","description":"1940年1月，隶属苏军第20重坦克旅的一队T-28中型坦克正在芬兰卡累利亚峽谷驶向阵地。注意坦克已配备72.6mm的L-10火炮。","caption":""},{"image":"imgs/ru/army/ru_army_tankt2835_33.jpg","description":"1940年2月，隶属苏军第20重坦克旅的一辆T-28中型坦克正在穿越芬兰卡累利阿峽谷树林地带。","caption":""},{"image":"imgs/ru/army/ru_army_tankt2835_34.jpg","description":"1940年1月，一辆被芬兰军队缴获的苏军T-28中型坦克，芬兰士兵正驾驶着行进。","caption":""},{"image":"imgs/ru/army/ru_army_tankt2835_35.jpg","description":"1940年4月24日，列宁格勒民众迎接从芬兰前线返回后方基地的苏军第20重坦克旅的T-28中型坦克及其坦克手。","caption":""},{"image":"imgs/ru/army/ru_army_tankt2835_36.jpg","description":"1940年11月7日，一队T-28中型坦克参加苏联十月革命庆典阅兵。","caption":""},{"image":"imgs/ru/army/ru_army_tankt2835_37.jpg","description":"1941年7月，东线苏联战场，一辆隶属苏联西北方面军第3装甲师的T-28中型坦克被苏军车组成员主动损坏后遗弃，几名德军技术人员正在检查该辆坦克的损毁情况。","caption":""},{"image":"imgs/ru/army/ru_army_tankt2835_38.jpg","description":"1942年冬季，一辆隶属苏联列宁格勒方面军第51独立坦克营的T-28中型坦克陷在雪地中。","caption":""},{"image":"imgs/ru/army/ru_army_tankt2835_39.jpg","description":"1942年冬季，苏联列宁格勒方面军第51独立坦克营一辆编号为“230”的T-28中型坦克和它的车组成员（车长是斯韦林中士）。","caption":""},{"image":"imgs/ru/army/ru_army_tankt2835_40.jpg","description":"一辆被德国空军摧毁的T-28中型坦克，该坦克隶属苏联西南方面军第15机械化军。","caption":""},{"image":"imgs/ru/army/ru_army_tankt2835_41.jpg","description":"苏军一高级政委正在向装备T-28中型坦克部队指战员进行战斗动员，指战员后面是两辆T-28坦克。","caption":""},{"image":"imgs/ru/army/ru_army_tankt2835_42.jpg","description":"图中是二辆隶属苏联西南方面军机械化第8军的T-28中型坦克。前面一辆是1937-1940年生产，编号3323；后面一辆是1936-1937年生产，编号2023。照片摄于1941年8月初。","caption":""},{"image":"imgs/ru/army/ru_army_tankt2835_43.jpg","description":"苏联卫国战争初期被德军缴获的一辆T-35重型坦克。相比站在车体边的2名德军士兵来说，该坦克体型显得十分巨大。","caption":""}]}')}});